/* ao aprovar uma etapa, o Make tira as outras tags dessa mesma etapa (nomes novos e antigos; o histórico das etapas anteriores fica) */
const LIMPAR={'captado':['Para Captação','Para Capitação'],
 'ideia aprovada':['Analisar Ideia','Ajustar Ideia','Não entendi a ideia','Ideia não aprovada','ideia não aprovada','Análisar Ideia','análise de ideia','ajuste de ideia','Ideia Reprovada'],
 'roteiro aprovado':['Analise Roteiro','Ajustes no Roteiro','Analise do Roteiro','Ajustes de Roteiro','análise de roteiro','ajuste de roteiro'],
 'criativo aprovado':['Análise do criativo','análise do criativo','Ajuste no criativo','ajuste no criativo','Analise de Criativo','Ajuste de Criativo']
};
function payload(it){
 const e=etapaDe(it.etapa),i=stat(it),tag=e.tags[i],lim=LIMPAR[tag]||[];
 const p={chave:CHAVE,cliente:CLIENTE,item:it.id,pagina:it.pagina,ts:new Date().toISOString(),etapa:it.etapa,ideia:String(it.numero),titulo:it.titulo,rotulo:'#'+it.numero+' · '+it.titulo,tag:tag,status:ST_NOTION[tag]||'',obs:(obs[it.id]||'').trim()};
 for(let n=1;n<=9;n++)p['r'+n]=lim[n-1]||'';
 return p;
}
